    m = _YEAR_FIRST.match(text)
    if m:
        year, month, day = m.groups()
    else:
        m = _DAY_FIRST.match(text)
        if m:
            day, month, year = m.groups()
        else:
            year, month, day = split_date(text)
    return (int(year), int(month), int(day))

