"""Date parsing for invoice imports."""

import re

_ISO = re.compile(r"^(\d{4})-(\d{1,2})-(\d{1,2})$")      # YYYY-MM-DD
_SLASH = re.compile(r"^(\d{4})/(\d{1,2})/(\d{1,2})$")    # YYYY/MM/DD
_DOTTED = re.compile(r"^(\d{1,2})\.(\d{1,2})\.(\d{4})$")  # DD.MM.YYYY (day first)


def parse_date(text):
    """Parse an import date into a (year, month, day) tuple of ints."""
    text = text.strip()
    for pattern in (_ISO, _SLASH):
        m = pattern.match(text)
        if m:
            year, month, day = m.groups()
            return (int(year), int(month), int(day))
    m = _DOTTED.match(text)
    if m:
        day, month, year = m.groups()
        return (int(year), int(month), int(day))
    raise ValueError(f"Unsupported date format: {text!r}")

{
  "summary": "Make parse_date in app/parser.py handle YYYY/MM/DD and day-first DD.MM.YYYY in addition to ISO dates, fixing the invoice import crash in #412.",
  "ci_status": "green",
  "failing_tests": []
}

